import json, re, os, sys
PATH = 'storage/shared/meta/sas/beacons/CPS_v1_Zephyr_IV.jsonl'
OUT  = 'storage/shared/meta/sas/derived/cps_v1_final.json'
EXPECTED = 2.5

RX = {
    "A2p": re.compile(r"CPS_v1:\s*A2[_ ]?baseline[_ ]?sentinel", re.I),
    "D1":  re.compile(r"CPS_v1:\s*D1[_ ]?deep[_ ]?train", re.I),
    "D2":  re.compile(r"CPS_v1:\s*D2[_ ]?deep[_ ]?train", re.I),
    "D3":  re.compile(r"CPS_v1:\s*D3[_ ]?deep[_ ]?train", re.I),
    "R2p": re.compile(r"CPS_v1:\s*R2[_ ]?recovery[_ ]?sentinel", re.I),
}
TMAP = {"A2p":385, "D1":386, "D2":387, "D3":388, "R2p":390}

def fnum(x):
    try: return float(x)
    except: return None

def load_lines(path):
    recs=[]
    if not os.path.exists(path):
        return recs
    with open(path,'r',encoding='utf-8') as f:
        for line in f:
            line=line.strip()
            if not line: continue
            try:
                recs.append(json.loads(line))
            except Exception:
                pass
    return recs

def norm(r):
    return {
      'agent': r.get('agent'),
      'phase': r.get('phase_label') or r.get('phase') or r.get('notes') or '',
      'lt': r.get('last_sentinel_tick') or r.get('tick'),
      'delta': fnum(r.get('sentinel_delta')),
      'state': r.get('state'),
      'path_est': fnum(r.get('path_complexity_est'))
    }

recs = [norm(r) for r in load_lines(PATH) if isinstance(r, dict)]
# newest wins for each key
sel = {k: None for k in ["A2p","D1","D2","D3","R2p"]}
for r in recs:
    ph = r['phase'] or ''
    for k, rx in RX.items():
        if rx.search(ph):
            sel[k] = r

# fallback by last_sentinel_tick if any missing
for r in recs:
    try:
        lt = int(r['lt']) if r['lt'] is not None else None
    except Exception:
        lt = None
    if lt is not None:
        for k, t in TMAP.items():
            if sel[k] is None and lt == t:
                sel[k] = r

def ratio(dk, r2p):
    if not dk or not r2p: return None
    if r2p['delta'] and r2p['delta'] > 0 and dk['delta'] is not None:
        return dk['delta'] / r2p['delta']
    return None

out = {
  'source_path': PATH,
  'present': {k: sel[k] is not None for k in sel},
  'deltas': {k: (None if sel[k] is None else sel[k]['delta']) for k in sel},
  'states': {k: (None if sel[k] is None else sel[k]['state']) for k in sel},
  'ratios_vs_R2p': {
    'D1': ratio(sel['D1'], sel['R2p']),
    'D2': ratio(sel['D2'], sel['R2p']),
    'D3': ratio(sel['D3'], sel['R2p'])
  },
  'expected_ratio': EXPECTED
}
rs = [out['ratios_vs_R2p'][k] for k in ['D1','D2','D3'] if isinstance(out['ratios_vs_R2p'][k], (int,float))]
out['deep_mean_ratio_vs_R2p'] = (sum(rs)/len(rs) if rs else None)

# write derived summary for dashboards
os.makedirs(os.path.dirname(OUT), exist_ok=True)
with open(OUT, 'w', encoding='utf-8') as f:
    json.dump(out, f, indent=2)

print(json.dumps(out, indent=2))
